int main() { std::pair<int, int> p = {3, 4}; auto [a, b] = p; std::cout << a + b; }

#include <iostream>
#include <optional>
int main() { std::optional<int> o = 5; std::cout << o.value(); }

#include <iostream>
#include <variant>
int main() { std::variant<int, double> v = 42; std::cout << std::get<int>(v); }

#include <iostream>
#include <string_view>
int main() { std::string_view sv = "abc"; std::cout << sv.size(); }

#include <iostream>
#include <string>
int main() { std::string a = "hi"; std::string b = std::move(a); std::cout << b; }

#include <iostream>
#include <thread>
void work() { std::cout << "hi"; }
int main() { std::thread t(work); t.join(); }

#include <iostream>
#include <future>
int main() { auto f = std::async([] { return 6 * 7; }); std::cout << f.get(); }

#include <iostream>
#include <atomic>
int main() { std::atomic<int> a = 0; a++; std::cout << a.load(); }
